/** Set by vite.config.ts from LUMEN_APP_ID. */
declare const __LUMEN_APP_ID__: string;
/** a dev build (see app/vite.config.ts) */
declare const __LUMEN_DEV__: boolean;

/** Generated by vite.config.ts from app/private/ (empty when it is absent or LUMEN_PRIVATE=0). */
declare module 'virtual:lumen-private' {
	/** icon pack: file name slug -> file in iconpack/ */
	export const ICON_PACK: Record<string, string>;
	/** your own default wallpapers (app/private/wallpapers.json), or null for the bundled ones */
	export const PRIVATE_WALLPAPERS: {title: string; file: string}[] | null;
}
